]$entries$;
  eps CONSTANT float8 := 1e-6;
  f record;
  n int;
  n_old int;
  n_new int;
  n_inactive int;
  total int;
  listed int := 0;
  matched int := 0;
  at_new int := 0;
  at_old int := 0;
  neither int := 0;
  not_one int := 0;
  inactive int := 0;
BEGIN
  SELECT count(*) INTO total FROM public.spots WHERE created_by_user_id IS NULL;

  FOR f IN SELECT * FROM jsonb_to_recordset(entries) AS x(name text, prefecture text, old_lat float8, old_lng float8, new_lat float8, new_lng float8)
  LOOP
    listed := listed + 1;
    SELECT count(*),
           count(*) FILTER (WHERE abs(s.lat - f.old_lat) < eps AND abs(s.lng - f.old_lng) < eps),
           count(*) FILTER (WHERE abs(s.lat - f.new_lat) < eps AND abs(s.lng - f.new_lng) < eps),
           count(*) FILTER (WHERE s.status <> 'active')
      INTO n, n_old, n_new, n_inactive
      FROM public.spots s
     WHERE s.name = f.name AND s.prefecture = f.prefecture AND s.created_by_user_id IS NULL;
    IF n <> 1 THEN
      not_one := not_one + 1;
      CONTINUE;
    END IF;
    matched := matched + 1;
    IF n_old = 1 THEN
      at_old := at_old + 1;
    ELSIF n_new = 1 THEN
      at_new := at_new + 1;
    ELSE
      neither := neither + 1;
    END IF;
    IF n_inactive = 1 THEN
      inactive := inactive + 1;
    END IF;
  END LOOP;

  RAISE EXCEPTION 'RESULT total=% listed=% rest=% at_new=% at_old=% neither=% not_one=% inactive=%',
    total, listed, total - matched, at_new, at_old, neither, not_one, inactive;
END
$spot_coords_292_check$;
